{
  "task_id": "sca_bus_precharge_hamming_leak_001",
  "domain_id": "side_channel_fault_analysis",
  "title": "Precharged bus revealing operand Hamming weight",
  "description": "Analyze the precharge_bus_wrapper RTL module's two-phase precharge/evaluate bus protocol and produce a structured findings report describing how bus switching activity relates to the transported data word, along with a concrete hardening proposal.",
  "input_artifacts": [
    "inputs/precharge_bus_wrapper.v",
    "inputs/fault_model.json",
    "inputs/design_brief.md",
    "inputs/activity_trace_template.txt"
  ],
  "expected_outputs": [
    "submission/vulnerability_report.json"
  ],
  "submission_artifacts": [
    "submission/vulnerability_report.json"
  ],
  "metrics": [
    {
      "name": "leakage_detection_accuracy",
      "description": "Whether the report correctly identifies the leaking phase and the nature of the switching-activity-based leakage metric, scored against hidden ground truth."
    },
    {
      "name": "fault_coverage",
      "description": "Whether the report identifies the complete set of affected bus nets and the correct transfer timing offsets, rather than a partial or incorrect subset."
    },
    {
      "name": "hardening_precision",
      "description": "Whether the proposed mitigation specifically achieves constant transition-count balancing while explicitly preserving correct data transport, as opposed to vague, irrelevant, or functionality-breaking suggestions."
    },
    {
      "name": "schema_conformance",
      "description": "Whether the submitted vulnerability_report.json contains all required fields in the correct types per the response format."
    }
  ]
}

`timescale 1ns / 1ps

module precharge_bus_wrapper (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       load,
    input  wire [7:0] data_in,
    output reg  [7:0] dbus,
    output reg        valid
);

    // Simple 3-state transfer sequencer.
    localparam ST_IDLE      = 2'b00;
    localparam ST_PRECHARGE = 2'b01;
    localparam ST_EVALUATE  = 2'b10;

    reg [1:0] state;
    reg [7:0] data_latched;

    always @(posedge clk) begin
        if (!rst_n) begin
            state        <= ST_IDLE;
            dbus         <= 8'h00;
            valid        <= 1'b0;
            data_latched <= 8'h00;
        end else begin
            case (state)
                ST_IDLE: begin
                    valid <= 1'b0;
                    if (load) begin
                        data_latched <= data_in;
                        state        <= ST_PRECHARGE;
                    end
                end

                ST_PRECHARGE: begin
                    dbus  <= 8'h00;
                    valid <= 1'b0;
                    state <= ST_EVALUATE;
                end

                ST_EVALUATE: begin
                    dbus  <= data_latched;
                    valid <= 1'b1;
                    state <= ST_IDLE;
                end

                default: begin
                    state <= ST_IDLE;
                end
            endcase
        end
    end

endmodule
